const revokeServerKey = `-- name: RevokeServerKey :one
UPDATE server_keys
SET revoked_at = now(), revoked_reason = $2
WHERE id = $1 AND revoked_at IS NULL
RETURNING id, server_id, name, key_prefix, key_hash, scopes, issued_at, expires_at, last_used_at, last_used_ip, revoked_at, revoked_reason, created_by
`

type RevokeServerKeyParams struct {
	ID            int64   `json:"id"`
	RevokedReason *string `json:"revoked_reason"`
}

// ⚠️ 轮换强制两步（data-model §8.3）：先 CreateServerKey → 确认节点已用新密钥上报
//
//	→ 才 RevokeServerKey 旧的。一步完成 = 节点在下一次 60 秒轮询时失联。
func (q *Queries) RevokeServerKey(ctx context.Context, arg RevokeServerKeyParams) (ServerKey, error) {
	row := q.db.QueryRow(ctx, revokeServerKey, arg.ID, arg.RevokedReason)
	var i ServerKey
	err := row.Scan(
		&i.ID,
		&i.ServerID,
		&i.Name,
		&i.KeyPrefix,
		&i.KeyHash,
		&i.Scopes,
		&i.IssuedAt,
		&i.ExpiresAt,
		&i.LastUsedAt,
		&i.LastUsedIp,
		&i.RevokedAt,
		&i.RevokedReason,
		&i.CreatedBy,
	)
	return i, err
}

