const updateServer = `-- name: UpdateServer :one
UPDATE servers SET
  name = $2, protocol = $3, host = $4, port = $5, server_port = $6, region = $7,
  parent_id = $8, protocol_settings = $9, tags = $10,
  enabled = $11, visible = $12, sort_order = $13, updated_at = now()
WHERE id = $1 AND deleted_at IS NULL
RETURNING id, code, name, protocol, host, port, server_port, region, parent_id, protocol_settings, tags, enabled, visible, sort_order, created_at, updated_at, deleted_at
`

type UpdateServerParams struct {
	ID               int64          `json:"id"`
	Name             string         `json:"name"`
	Protocol         ServerProtocol `json:"protocol"`
	Host             string         `json:"host"`
	Port             int32          `json:"port"`
	ServerPort       *int32         `json:"server_port"`
	Region           string         `json:"region"`
	ParentID         *int64         `json:"parent_id"`
	ProtocolSettings []byte         `json:"protocol_settings"`
	Tags             []string       `json:"tags"`
	Enabled          bool           `json:"enabled"`
	Visible          bool           `json:"visible"`
	SortOrder        int32          `json:"sort_order"`
}

// ⚠️ 调用方必须在同一事务里 BumpConfigRev，否则节点会一直拿旧配置的 304。
func (q *Queries) UpdateServer(ctx context.Context, arg UpdateServerParams) (Server, error) {
	row := q.db.QueryRow(ctx, updateServer,
		arg.ID,
		arg.Name,
		arg.Protocol,
		arg.Host,
		arg.Port,
		arg.ServerPort,
		arg.Region,
		arg.ParentID,
		arg.ProtocolSettings,
		arg.Tags,
		arg.Enabled,
		arg.Visible,
		arg.SortOrder,
	)
	var i Server
	err := row.Scan(
		&i.ID,
		&i.Code,
		&i.Name,
		&i.Protocol,
		&i.Host,
		&i.Port,
		&i.ServerPort,
		&i.Region,
		&i.ParentID,
		&i.ProtocolSettings,
		&i.Tags,
		&i.Enabled,
		&i.Visible,
		&i.SortOrder,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}

const upsertServerOnlineState = `-- name: UpsertServerOnlineState :exec

INSERT INTO server_online_state (
  server_id, online_users, cpu_pct,
  mem_total, mem_used, swap_total, swap_used, disk_total, disk_used, reported_at
) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, now())
ON CONFLICT (server_id) DO UPDATE SET
  online_users = EXCLUDED.online_users,
  cpu_pct      = EXCLUDED.cpu_pct,
  mem_total    = EXCLUDED.mem_total,
  mem_used     = EXCLUDED.mem_used,
  swap_total   = EXCLUDED.swap_total,
  swap_used    = EXCLUDED.swap_used,
  disk_total   = EXCLUDED.disk_total,
  disk_used    = EXCLUDED.disk_used,
  reported_at  = now()
`

type UpsertServerOnlineStateParams struct {
	ServerID    int64    `json:"server_id"`
	OnlineUsers int32    `json:"online_users"`
	CpuPct      *float32 `json:"cpu_pct"`
	MemTotal    *int64   `json:"mem_total"`
	MemUsed     *int64   `json:"mem_used"`
	SwapTotal   *int64   `json:"swap_total"`
	SwapUsed    *int64   `json:"swap_used"`
	DiskTotal   *int64   `json:"disk_total"`
	DiskUsed    *int64   `json:"disk_used"`
}

// ============================================================
// POST /api/v1/server/UniProxy/status — 节点负载（只写快照，不建历史表）
// ============================================================
// 校验（cpu 0–100、其余 ≥ 0）在 handler 做，schema 只保住 cpu_pct 的区间。
func (q *Queries) UpsertServerOnlineState(ctx context.Context, arg UpsertServerOnlineStateParams) error {
	_, err := q.db.Exec(ctx, upsertServerOnlineState,
		arg.ServerID,
		arg.OnlineUsers,
		arg.CpuPct,
		arg.MemTotal,
		arg.MemUsed,
		arg.SwapTotal,
		arg.SwapUsed,
		arg.DiskTotal,
		arg.DiskUsed,
	)
	return err
}
